// ------------------------------------------------------------------ lexer
enum TokType : uint8_t { TK_END, TK_NUM, TK_ID, TK_OP, TK_ERR };

struct Lexer {
  const char* s;
  size_t pos;
  TokType type;
  double num;
  char text[NAME_MAX];

  static bool idStart(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == '$'; }
  static bool idChar(char c) { return idStart(c) || (c >= '0' && c <= '9'); }
  static bool digit(char c) { return c >= '0' && c <= '9'; }

  void error(const char* msg) { type = TK_ERR; strncpy(text, msg, NAME_MAX - 1); text[NAME_MAX - 1] = 0; }

  bool readIdent() {
    size_t n = 0;
    while (idChar(s[pos])) {
      if (n >= NAME_MAX - 1) { error("name too long"); return false; }
      text[n++] = s[pos++];
    }
    text[n] = 0;
    return true;
  }

  void next() {
    for (;;) {
      while (s[pos] == ' ' || s[pos] == '\t' || s[pos] == '\n' || s[pos] == '\r') pos++;
      if (s[pos] == '/' && s[pos + 1] == '/') { while (s[pos] && s[pos] != '\n') pos++; continue; }
      break;
    }
    char c = s[pos];
    if (!c) { type = TK_END; text[0] = 0; return; }
    if (digit(c) || (c == '.' && digit(s[pos + 1]))) {
      size_t st = pos;
      while (digit(s[pos])) pos++;
      if (s[pos] == '.') { pos++; while (digit(s[pos])) pos++; }
      if (s[pos] == 'e' || s[pos] == 'E') {
        size_t p = pos + 1;
        if (s[p] == '+' || s[p] == '-') p++;
        if (digit(s[p])) { pos = p; while (digit(s[pos])) pos++; }
      }
      char buf[40];
      size_t n = pos - st;
      if (n >= sizeof(buf)) { error("number too long"); return; }
      memcpy(buf, s + st, n);
      buf[n] = 0;
      num = strtod(buf, nullptr);
      type = TK_NUM;
      return;
    }
    if (idStart(c)) {
      if (!readIdent()) return;
      if (strcmp(text, "Math") == 0 && s[pos] == '.' && idStart(s[pos + 1])) { pos++; if (!readIdent()) return; }
      type = TK_ID;
      return;
    }
    static const char* const OPS[] = { "===", "!==", "**", "<=", ">=", "==", "!=", "&&", "||", "=>" };
    for (const char* op : OPS) {
      size_t n = strlen(op);
      if (strncmp(s + pos, op, n) == 0) { memcpy(text, op, n + 1); pos += n; type = TK_OP; return; }
    }
    if (strchr("+-*/%<>!?:(),;{}=", c)) { text[0] = c; text[1] = 0; pos++; type = TK_OP; return; }
    char msg[NAME_MAX];
    snprintf(msg, sizeof(msg), "unexpected '%c'", c);
    error(msg);
  }
};

// ------------------------------------------------------------------ parser
struct Compiler {
  Lexer lx;
  std::vector<ExprOp>& ops;
  char* err;
  size_t errLen;
  bool failed = false;
  int depth = 0;
  char params[4][NAME_MAX];
  int nParams = 0;
  char locals[EXPR_MAX_LOCALS][NAME_MAX];
  int nLocals = 0;

  Compiler(const char* src, std::vector<ExprOp>& o, char* e, size_t el) : ops(o), err(e), errLen(el) {
    lx.s = src; lx.pos = 0;
  }

  void fail(const char* msg) {
    if (failed) return;
    failed = true;
    if (err && errLen) snprintf(err, errLen, "%s", msg);
  }
  void next() { lx.next(); if (lx.type == TK_ERR) fail(lx.text); }
  bool isOp(const char* o) const { return lx.type == TK_OP && strcmp(lx.text, o) == 0; }
  bool isWord(const char* w) const { return lx.type == TK_ID && strcmp(lx.text, w) == 0; }
  void expect(const char* o) {
    if (failed) return;
    if (!isOp(o)) { char m[48]; snprintf(m, sizeof(m), "expected '%s'", o); fail(m); return; }
    next();
  }
  void emit(uint8_t code, uint8_t arg, uint8_t n, double v, int delta) {
    if (failed) return;
    if ((int)ops.size() >= EXPR_MAX_OPS) { fail("expression too long"); return; }
    ops.push_back({ code, arg, n, v });
    depth += delta;
    if (depth > EXPR_MAX_STACK) fail("expression too deeply nested");
  }

  // optional "(a, b) =>" or "a =>" header; names bind positionally to pieces, t, et, level
  void header() {
    Lexer save = lx;
    char names[4][NAME_MAX];
    int n = 0;
    if (lx.type == TK_ID) {
      strcpy(names[0], lx.text);
      lx.next();
      if (isOp("=>")) { strcpy(params[0], names[0]); nParams = 1; next(); return; }
      lx = save;
      return;
    }
    if (!isOp("(")) return;
    lx.next();
    if (!isOp(")")) {
      for (;;) {
        if (lx.type != TK_ID || n >= 4) { lx = save; return; }
        strcpy(names[n++], lx.text);
        lx.next();
        if (isOp(",")) { lx.next(); continue; }
        break;
      }
    }
    if (!isOp(")")) { lx = save; return; }
    lx.next();
    if (!isOp("=>")) { lx = save; return; }
    for (int i = 0; i < n; i++) strcpy(params[i], names[i]);
    nParams = n;
    next();
  }

  void program() {
    next();
    if (failed) return;
    header();
    if (isOp("{")) {
      next();
      for (;;) {
        if (failed) return;
        if (isWord("let") || isWord("const") || isWord("var")) {
          next();
          if (lx.type != TK_ID) { fail("expected a name"); return; }
          char name[NAME_MAX];
          strcpy(name, lx.text);
          next();
          expect("=");
          expr();
          int slot = -1;
          for (int i = nLocals - 1; i >= 0; i--) if (strcmp(locals[i], name) == 0) { slot = i; break; }
          if (slot < 0) {
            if (nLocals >= EXPR_MAX_LOCALS) { fail("too many variables"); return; }
            strcpy(locals[nLocals], name);
            slot = nLocals++;
          }
          emit(X_STORE, XV_COUNT + slot, 0, 0, -1);
          if (isOp(";")) next();
        } else if (isWord("return")) {
          next();
          expr();
          if (isOp(";")) next();
          expect("}");
          break;
        } else {
          fail("expected let, const or return");
          return;
        }
      }
    } else {
      expr();
    }
    if (isOp(";")) next();
    if (!failed && lx.type != TK_END) fail("unexpected text after the expression");
    if (!failed && depth != 1) fail("expected a value");
  }

  void expr() {  // ternary, right-associative
    orExpr();
    if (isOp("?")) {
      next(); expr();
      expect(":"); expr();
      emit(X_SEL, 0, 0, 0, -2);
    }
  }
  void orExpr() { andExpr(); while (!failed && isOp("||")) { next(); andExpr(); emit(X_OR, 0, 0, 0, -1); } }
  void andExpr() { eqExpr(); while (!failed && isOp("&&")) { next(); eqExpr(); emit(X_AND, 0, 0, 0, -1); } }
  void eqExpr() {
    relExpr();
    while (!failed) {
      uint8_t op;
      if (isOp("==") || isOp("===")) op = X_EQ;
      else if (isOp("!=") || isOp("!==")) op = X_NE;
      else break;
      next(); relExpr(); emit(op, 0, 0, 0, -1);
    }
  }
  void relExpr() {
    addExpr();
    while (!failed) {
      uint8_t op;
      if (isOp("<")) op = X_LT; else if (isOp("<=")) op = X_LE;
      else if (isOp(">")) op = X_GT; else if (isOp(">=")) op = X_GE;
      else break;
      next(); addExpr(); emit(op, 0, 0, 0, -1);
    }
  }
  void addExpr() {
    mulExpr();
    while (!failed && (isOp("+") || isOp("-"))) {
      uint8_t op = isOp("+") ? X_ADD : X_SUB;
      next(); mulExpr(); emit(op, 0, 0, 0, -1);
    }
  }
  void mulExpr() {
    unary();
    while (!failed && (isOp("*") || isOp("/") || isOp("%"))) {
      uint8_t op = isOp("*") ? X_MUL : (isOp("/") ? X_DIV : X_MOD);
      next(); unary(); emit(op, 0, 0, 0, -1);
    }
  }
  void unary() {
    if (isOp("-")) { next(); unary(); emit(X_NEG, 0, 0, 0, 0); return; }
    if (isOp("+")) { next(); unary(); return; }
    if (isOp("!")) { next(); unary(); emit(X_NOT, 0, 0, 0, 0); return; }
    power();
  }
  void power() {
    primary();
    if (isOp("**")) { next(); unary(); emit(X_POW, 0, 0, 0, -1); }
  }
  void primary() {
    if (failed) return;
    if (lx.type == TK_NUM) { emit(X_CONST, 0, 0, lx.num, 1); next(); return; }
    if (isOp("(")) { next(); expr(); expect(")"); return; }
    if (lx.type != TK_ID) {
      if (lx.type == TK_END) fail("unexpected end"); else { char m[48]; snprintf(m, sizeof(m), "unexpected '%s'", lx.text); fail(m); }
      return;
    }
    char name[NAME_MAX];
    strcpy(name, lx.text);
    next();
    if (isOp("(")) { call(name); return; }
    for (int i = nLocals - 1; i >= 0; i--) if (strcmp(locals[i], name) == 0) { emit(X_LOAD, XV_COUNT + i, 0, 0, 1); return; }
    for (int i = 0; i < nParams; i++) if (strcmp(params[i], name) == 0) { emit(X_LOAD, i, 0, 0, 1); return; }
    for (int i = 0; i < XV_COUNT; i++) if (strcmp(VAR_NAMES[i], name) == 0) { emit(X_LOAD, i, 0, 0, 1); return; }
    if (strcmp(name, "PI") == 0) { emit(X_CONST, 0, 0, TAU_D / 2, 1); return; }
    if (strcmp(name, "TAU") == 0) { emit(X_CONST, 0, 0, TAU_D, 1); return; }
    if (strcmp(name, "E") == 0) { emit(X_CONST, 0, 0, 2.718281828459045, 1); return; }
    if (strcmp(name, "true") == 0) { emit(X_CONST, 0, 0, 1, 1); return; }
    if (strcmp(name, "false") == 0) { emit(X_CONST, 0, 0, 0, 1); return; }
    char m[48];
    snprintf(m, sizeof(m), "unknown name '%s'", name);
    fail(m);
  }
  void call(const char* name) {
    const FuncDef* f = nullptr;
    for (const FuncDef& d : FUNCS) if (strcmp(d.name, name) == 0) { f = &d; break; }
    if (!f) { char m[48]; snprintf(m, sizeof(m), "unknown function '%s'", name); fail(m); return; }
    next();  // '('
    int argc = 0;
    if (!isOp(")")) {
      for (;;) {
        expr();
        argc++;
        if (failed) return;
        if (isOp(",")) { next(); continue; }
        break;
      }
    }
    expect(")");
    if (failed) return;
    if (argc < f->minArgs || argc > f->maxArgs) {
      char m[48];
      if (f->minArgs == f->maxArgs) snprintf(m, sizeof(m), "%s() takes %d argument%s", f->name, f->minArgs, f->minArgs == 1 ? "" : "s");
      else snprintf(m, sizeof(m), "%s() takes %d to %d arguments", f->name, f->minArgs, f->maxArgs);
      fail(m);
      return;
    }
    emit(X_FN, f->id, (uint8_t)argc, 0, 1 - argc);
  }
};

bool ExprProgram::compile(const char* src, char* err, size_t errLen) {
  _ops.clear();
  if (strlen(src) > (size_t)EXPR_MAX_SRC) { if (err && errLen) snprintf(err, errLen, "expression too long"); return false; }
  std::vector<ExprOp> ops;
  Compiler c(src, ops, err, errLen);
  c.program();
  if (c.failed) return false;
  _ops.swap(ops);
  return true;
}

// ------------------------------------------------------------------ evaluation
static inline uint32_t xHash32(uint32_t x) {
  x ^= x >> 16; x *= 0x7feb352dU;
  x ^= x >> 15; x *= 0x846ca68bU;
  x ^= x >> 16;
  return x;
}
static inline double xU01(uint32_t h) { return (double)(h >> 8) / 16777216.0; }
static inline uint32_t toU32(double x) { return (uint32_t)(int64_t)x; }  // x already floored; wraps like JS >>> 0
static inline bool truthy(double x) { return x != 0 && x == x; }
static inline double fract(double x) { return x - std::floor(x); }

static double noise1(double x) {
  double fl = std::floor(x), f = x - fl;
  uint32_t i = toU32(fl);
  double g0 = xU01(xHash32(i)) * 2 - 1, g1 = xU01(xHash32(i + 1)) * 2 - 1;
  double d0 = g0 * f, d1 = g1 * (f - 1);
  double u = f * f * f * (f * (f * 6 - 15) + 10);
  double n = 0.5 + d0 + (d1 - d0) * u;
  return n < 0 ? 0 : (n > 1 ? 1 : n);
}

static double callFn(uint8_t id, const double* a, int n) {
  switch (id) {
    case F_SIN: return std::sin(a[0]);
    case F_COS: return std::cos(a[0]);
    case F_TAN: return std::tan(a[0]);
    case F_ASIN: return std::asin(a[0]);
    case F_ACOS: return std::acos(a[0]);
    case F_ATAN: return std::atan(a[0]);
    case F_ATAN2: return std::atan2(a[0], a[1]);
    case F_SQRT: return std::sqrt(a[0]);
    case F_ABS: return std::fabs(a[0]);
    case F_FLOOR: return std::floor(a[0]);
    case F_CEIL: return std::ceil(a[0]);
    case F_ROUND: return std::floor(a[0] + 0.5);
    case F_TRUNC: return std::trunc(a[0]);
    case F_SIGN: return a[0] > 0 ? 1 : (a[0] < 0 ? -1 : a[0]);
    case F_EXP: return std::exp(a[0]);
    case F_LOG: return std::log(a[0]);
    case F_POW: return std::pow(a[0], a[1]);
    case F_MIN: { double r = a[0]; for (int i = 1; i < n; i++) if (a[i] < r || a[i] != a[i]) r = a[i]; return r; }
    case F_MAX: { double r = a[0]; for (int i = 1; i < n; i++) if (a[i] > r || a[i] != a[i]) r = a[i]; return r; }
    case F_FRACT: return fract(a[0]);
    case F_MOD: return a[0] - a[1] * std::floor(a[0] / a[1]);
    case F_CLAMP: { double r = a[0] < a[1] ? a[1] : a[0]; return r > a[2] ? a[2] : r; }
    case F_LERP: return a[0] + (a[1] - a[0]) * a[2];
    case F_SMOOTHSTEP: {
      if (a[0] == a[1]) return a[2] < a[0] ? 0 : 1;
      double t = (a[2] - a[0]) / (a[1] - a[0]);
      t = t < 0 ? 0 : (t > 1 ? 1 : t);
      return t * t * (3 - 2 * t);
    }
    case F_WAVE: return 0.5 + 0.5 * std::sin(TAU_D * a[0]);
    case F_TRIANGLE: return 1 - std::fabs(2 * fract(a[0]) - 1);
    case F_SQUARE: return fract(a[0]) < (n > 1 ? a[1] : 0.5) ? 1 : 0;
    case F_NOISE: return noise1(a[0]);
    case F_RND: return xU01(xHash32(toU32(std::floor(a[0]))));
  }
  return 0;
}

double ExprProgram::eval(const double* vars) const {
  double st[EXPR_MAX_STACK];
  double slot[XV_COUNT + EXPR_MAX_LOCALS] = {};
  for (int i = 0; i < XV_COUNT; i++) slot[i] = vars[i];
  int sp = 0;
  for (const ExprOp& op : _ops) {
    switch (op.code) {
      case X_CONST: st[sp++] = op.v; break;
      case X_LOAD:  st[sp++] = slot[op.arg]; break;
      case X_STORE: slot[op.arg] = st[--sp]; break;
      case X_NEG:   st[sp - 1] = -st[sp - 1]; break;
      case X_NOT:   st[sp - 1] = truthy(st[sp - 1]) ? 0 : 1; break;
      case X_SEL:   sp -= 2; st[sp - 1] = truthy(st[sp - 1]) ? st[sp] : st[sp + 1]; break;
      case X_FN:    sp -= op.n; st[sp] = callFn(op.arg, st + sp, op.n); sp++; break;
      default: {
        double b = st[--sp], a = st[sp - 1], r = 0;
        switch (op.code) {
          case X_ADD: r = a + b; break;
          case X_SUB: r = a - b; break;
          case X_MUL: r = a * b; break;
          case X_DIV: r = a / b; break;
          case X_MOD: r = std::fmod(a, b); break;
          case X_POW: r = std::pow(a, b); break;
          case X_LT:  r = a < b; break;
          case X_LE:  r = a <= b; break;
          case X_GT:  r = a > b; break;
          case X_GE:  r = a >= b; break;
          case X_EQ:  r = a == b; break;
          case X_NE:  r = a != b; break;
          case X_AND: r = truthy(a) ? b : a; break;
          case X_OR:  r = truthy(a) ? a : b; break;
        }
        st[sp - 1] = r;
      }
    }
  }
  return sp > 0 ? st[sp - 1] : 0;
}

